18	// on-disk layout inside the data directory:
19	//
20	//	data.json    – the committed state (JSON envelope, atomically replaced)
21	//	data.json.tmp– staging file for the next commit (rename(2) target)
22	//	lock         – flock file serializing concurrent processes
23	//
24	// The envelope carries an explicit format version: files written by an
25	// incompatible future build are refused rather than silently migrated or
26	// overwritten.
27	const (
28		dirDataFile = "data.json"
29		dirTmpFile  = "data.json.tmp"
30		dirLockFile = "lock"
31	
32		// FormatVersion is the on-disk format this build writes and accepts.
33		FormatVersion = 1
34	)
35	
36	// envelope is the persisted state container.
37	//
38	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
39	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
40	// decides what a committed circuit record may look like. UnmarshalJSON first
41	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
42	// object key anywhere encoding/json would otherwise keep the last value. At
43	// the envelope's top level that comparison is case-insensitive for the five
44	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
45	// that differs only in ASCII letter case — including one JSON-escaped — names
46	// the same field and corrupts the read instead of overriding it. A spelling
47	// that Unicode case-folds onto one of those fields yet is not an ASCII case
48	// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
49	// is likewise corruption even when it is the only spelling present, since
50	// encoding/json's own tag matching would fill the field from it; a later
51	// "circuitſ": [] must never read the circuits as empty and drop them on the
52	// next commit.
53	type envelope struct {
54		Format    int               `json:"format"`
55		Circuits  []persistCircuit  `json:"circuits"`
56		Setups    []persistSetup    `json:"setups"`
57		Jobs      []persistJob      `json:"jobs"`
58		Artifacts []persistArtifact `json:"artifacts,omitempty"`
59	}
60	
61	// envelopeWire is the decoding-only shape: circuit records arrive raw so
62	// their own strict decoder can require every field explicitly.
63	type envelopeWire struct {
64		Format    int               `json:"format"`
65		Circuits  []json.RawMessage `json:"circuits"`
66		Setups    []persistSetup    `json:"setups"`
67		Jobs      []persistJob      `json:"jobs"`
68		Artifacts []persistArtifact `json:"artifacts,omitempty"`
69	}
70	
71	func (e *envelope) UnmarshalJSON(raw []byte) error {
72		// Reject repeated keys before decoding: encoding/json silently keeps the
73		// last value of a duplicate. The walk is layered so a repeated field is
74		// attributed to the record it belongs to (a duplicate "frozen" inside
75		// circuit #3, not a generic envelope complaint).
76		if err := scanEnvelopeDuplicates(raw); err != nil {
77			return err
78		}
79		var wire envelopeWire
80		if err := json.Unmarshal(raw, &wire); err != nil {
81			var se StoreError
82			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
83				return err // an inner record decoder already named the problem
84			}
85			return corruptf("data file envelope is not valid JSON: %v", err)
86		}
87		e.Format = wire.Format
88		e.Setups = wire.Setups
89		e.Jobs = wire.Jobs
90		e.Artifacts = wire.Artifacts
91		if wire.Circuits == nil {
92			e.Circuits = nil
93		} else {
94			e.Circuits = make([]persistCircuit, len(wire.Circuits))
95		}
96		for i, craw := range wire.Circuits {
97			var record persistCircuit
98			if err := json.Unmarshal(craw, &record); err != nil {
99				var se StoreError
100				if errors.As(err, &se) {
101					// Re-tag as one corruption error carrying the record index,
102					// so the detail survives errors.As unwrapping in loadLocked.
103					return StoreError{Kind: ErrDataCorrupt.Kind,
104						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
105				}
106				return corruptf("circuit record #%d: %v", i+1, err)
107			}
108			e.Circuits[i] = record
109		}
110		return nil
111	}
112	
113	// envelopeTopFields are the five fields an envelope may carry. Their
114	// canonical (standard lowercase) spellings are the wire tags on envelope and
115	// envelopeWire; JSON keys are tokenized after unescaping.
116	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
117	
118	// canonicalEnvelopeField reports the standard lowercase name of one of the
119	// five envelope fields when key names it under any ASCII letter-case spelling
120	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
121	// tokenizer, so an escaped spelling of any such form lands here too. A
122	// non-canonical key (different length or a mismatching byte, including
123	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
124	func canonicalEnvelopeField(key string) string {
125		for _, field := range envelopeTopFields {
126			if len(key) != len(field) {
127				continue
128			}
129			i := 0
130			for i < len(key) {
131				c := key[i]
132				if c >= 'A' && c <= 'Z' {
133					c += 'a' - 'A'
134				}
135				if c != field[i] {
136					break
137				}
138				i++
139			}
140			if i == len(field) {
141				return field
142			}
143		}
144		return ""
145	}
146	
147	// envelopeFieldLookalike reports the standard lowercase name of one of the
148	// five envelope fields when key names it under a spelling encoding/json's
149	// struct-tag matching would fold onto the field but which is not an accepted
150	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
151	// matching folds with the Unicode simple case-folding rules
152	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
153	// the JSON escape u017f — keys arrive here already unescaped) names the
154	// circuits field exactly like "circuits", even standing alone. Such a
155	// lookalike is damage whatever its value: a later "circuitſ": [] would
156	// otherwise override a populated circuits array through last-value-wins and
157	// the records would vanish on the next commit. A key that does not fold onto
158	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
159	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
160	// the ordinary unknown-member handling.
161	func envelopeFieldLookalike(key string) string {
162		if canonicalEnvelopeField(key) != "" {
163			return "" // an accepted ASCII spelling, not a lookalike
164		}
165		for _, field := range envelopeTopFields {
166			if strings.EqualFold(key, field) {
167				return field
168			}
169		}
170		return ""
171	}
172	
173	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
174	// repeated object key. The five known top-level fields are identified case-
175	// insensitively: two spellings that differ only in ASCII letter case (both
176	// keys already JSON-unescaped at this point) are the same field, in whatever
177	// order they appear and whether or not their values agree, so a later
178	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
179	// json's last-value-wins struct matching. Such a pair is reported as a
180	// duplicated top-level field named by its standard lowercase spelling.
181	//
182	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
183	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
184	// directly written or ſ-escaped) is rejected outright as data corruption:
185	// encoding/json would match it onto the field, so ignoring it as unknown
186	// could let its value replace the real one (an empty array hiding every
187	// record), and accepting it would let the records vanish on the next commit.
188	// The rule holds for the lookalike appearing alone — value a legal record, an
189	// empty array or null alike — and for it appearing beside the canonical
190	// spelling or an ASCII case variant, in either order and whether the values
191	// agree. The error names both the standard field and the actual spelling.
192	//
193	// Circuit and job records are scanned one record at a time — their own
194	// top-level fields are checked here (with the record's 1-based index, or the
195	// job's id, reported) by scanCircuitArrayDuplicates and the shared job reader
196	// scanJobArray in job_record.go, while a nested value such as a constraint
197	// definition or an unknown job member's object is skipped and left to its own
198	// strict decoder. Every other envelope member is scanned recursively so a
199	// duplicated key anywhere in committed data fails the read instead of
200	// silently resolving to its last value.
201	func scanEnvelopeDuplicates(raw []byte) error {
202		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
203		dec.UseNumber()
204		open, err := dec.Token()
205		if err != nil || open != json.Delim('{') {
206			return corruptf("data file envelope must be a JSON object")
207		}
208		// Exact spellings retain the pre-existing check for unknown keys;
209		// canonical names remember a known field's first occurrence regardless
210		// of the case it was written in.
211		seenTop := make(map[string]bool)
212		seenCanonical := make(map[string]bool)
213		for dec.More() {
214			keyTok, err := dec.Token()
215			if err != nil {
216				return corruptf("data file envelope is not valid JSON: %v", err)
217			}
218			key, ok := keyTok.(string)
219			if !ok {
220				return corruptf("data file envelope is not valid JSON")
221			}
222			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
223			// matching would read as a known field ("circuitſ" with long s,
224			// directly written or ſ-escaped) before anything else. It is damage
225			// even on its own and whatever its value — a legal record, an empty
226			// array or null — and whether it precedes or follows the canonical or
227			// an ASCII case-variant spelling: the read may neither ignore it as an
228			// unknown member nor choose one of the values and carry on.
229			if canonical := envelopeFieldLookalike(key); canonical != "" {
230				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
231					canonical, key)
232			}
233			if canonical := canonicalEnvelopeField(key); canonical != "" {
234				if seenCanonical[canonical] {
235					if key == canonical {
236						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
237					}
238					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
239						canonical, key)
240				}
241				seenCanonical[canonical] = true
242				if canonical == "circuits" {
243					if err := scanCircuitArrayDuplicates(dec); err != nil {
244						return err
245					}
246					continue
247				}
248				if canonical == "jobs" {
249					if err := scanJobArray(dec); err != nil {
250						return err
251					}
252					continue
253				}
254				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
255					return err
256				}
257				continue
258			}
259			if seenTop[key] {
260				return corruptf("data file envelope contains duplicate field %q", key)
261			}
262			seenTop[key] = true
263			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
264				return err
265			}
266		}
267		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
268			return corruptf("data file envelope is not valid JSON")
269		}
270		if _, err := dec.Token(); err != io.EOF {
271			return corruptf("data file envelope is not valid JSON: trailing data after the object")
272		}
273		return nil
274	}
275	
276	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
277	// opening bracket and checks only each record's own top-level keys. The
278	// enclosing key may carry any case spelling, but the field it names is the
279	// canonical "circuits". A null array stays the pre-existing "no records"
280	// reading.
281	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
282		tok, err := dec.Token()
283		if err != nil {
284			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
285		}
286		if tok == nil { // null: json.Unmarshal would produce no records
287			return nil
288		}
289		if tok != json.Delim('[') {
290			return corruptf("data file envelope field \"circuits\" must be an array")
291		}
292		index := 0
293		for dec.More() {
294			index++
295			what := fmt.Sprintf("circuit record #%d", index)
296			open, err := dec.Token()
297			if err != nil {
298				return corruptf("%s is not valid JSON: %v", what, err)
299			}
300			if open == nil {
301				return corruptf("%s must be a JSON object, not null", what)
302			}
303			if open != json.Delim('{') {
304				return corruptf("%s must be a JSON object", what)
305			}
306			seen := make(map[string]bool)
307			for dec.More() {
308				keyTok, err := dec.Token()
309				if err != nil {
310					return corruptf("%s is not valid JSON: %v", what, err)
311				}
312				key, ok := keyTok.(string)
313				if !ok {
314					return corruptf("%s is not valid JSON", what)
315				}
316				if seen[key] {
317					return corruptf("%s contains duplicate field %q", what, key)
318				}
319				seen[key] = true
320				// Skip the whole value without descending: nested objects
321				// (definition) own their own strict duplicate checks.
322				var skip json.RawMessage
323				if err := dec.Decode(&skip); err != nil {
324					return corruptf("%s is not valid JSON: %v", what, err)
325				}
326			}
327			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
328				return corruptf("%s is not valid JSON", what)
329			}
330		}
331		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
332			return corruptf("data file envelope field \"circuits\" is not valid JSON")
333		}
334		return nil
335	}
336	
337	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
338	// recursively rejecting duplicate object keys.
339	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
340		tok, err := dec.Token()
341		if err != nil {
342			return corruptf("%s is not valid JSON: %v", what, err)
343		}
344		delim, ok := tok.(json.Delim)
345		if !ok {
346			return nil // scalar (including null)
347		}
348		switch delim {
349		case '{':
350			seen := make(map[string]bool)
351			for dec.More() {
352				keyTok, err := dec.Token()
353				if err != nil {
354					return corruptf("%s is not valid JSON: %v", what, err)
355				}
356				key, ok := keyTok.(string)
357				if !ok {
358					return corruptf("%s is not valid JSON", what)
359				}
360				if seen[key] {
361					return corruptf("%s contains duplicate field %q", what, key)
362				}
363				seen[key] = true
364				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
365					return err
366				}
367			}
368			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
369				return corruptf("%s is not valid JSON", what)
370			}
371		case '[':
372			index := 0
373			for dec.More() {
374				index++
375				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
376					return err
377				}
378			}
379			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
380				return corruptf("%s is not valid JSON", what)
381			}
382		}
383		return nil
384	}
385	
386	type persistTerm struct {
387		Wire  int    `json:"wire"`
388		Coeff string `json:"coeff"`
389	}
390	
391	type persistConstraint struct {
392		A []persistTerm `json:"a"`
393		B []persistTerm `json:"b"`
394		C []persistTerm `json:"c"`
395	}
396	
397	// persistDefinition is the canonical, already-validated constraint set bound
398	// to one circuit version. The public/private partition is owned by the
399	// circuit record and is deliberately not duplicated here, so it can never
400	// drift from the declared counts.
401	type persistDefinition struct {
402		Modulus     string              `json:"modulus"`
403		Constraints []persistConstraint `json:"constraints"`
404	}
405	
406	// persistArtifact is a compiled artifact: the version's identity and
407	// constraint count bound to its recomputable SHA-256 hash.
408	type persistArtifact struct {
409		Name        string `json:"name"`
410		Version     int    `json:"version"`
411		Modulus     int64  `json:"modulus"`
412		Constraints int    `json:"constraints"`
413		Hash        string `json:"hash"`
414	}
415	
416	type persistCircuit struct {
417		Name          string             `json:"name"`
418		Version       int                `json:"version"`
419		Constraints   int                `json:"constraints"`
420		PublicInputs  int                `json:"public_inputs"`
421		PrivateInputs int                `json:"private_inputs"`
422		Frozen        bool               `json:"frozen"`
423		Description   string             `json:"description"`
424		Definition    *persistDefinition `json:"definition,omitempty"`
425	}
426	
427	// Strict decoding of committed circuit records.
428	//
429	// A circuit record in data.json must name each of name, version, constraints,
430	// public_inputs, private_inputs, frozen and description exactly once, with
431	// the exact JSON type the writer emits (string / integer / integer / integer
432	// / integer / boolean / string). A missing key, a null, a wrong type or a
433	// repeated key is data corruption and refuses the whole directory read: a
434	// missing or null frozen flag must not silently read as false (turning a
435	// frozen version back into an editable draft), and a repeated key must not
436	// resolve to its last value. An explicit 0, false or "" is an ordinary value
437	// and stays legal. The definition member remains the one optional field: it
438	// may be absent or null (the legacy counts-only state); when present it goes
439	// through the strict persistDefinition decoder.
440	//
441	// The name field carries one rule beyond shape: its raw JSON string token
442	// must denote its value exactly — valid UTF-8 in the literal portions and no
443	// unpaired \uXXXX surrogate escapes (checkStoredStringEncoding). Both damage
444	// shapes decode to U+FFFD replacement characters under encoding/json, which
445	// would rename the circuit on read; they are data corruption, and the whole
446	// directory read is refused. Only the name is judged this way; every other
447	// field keeps the ordinary decoding rules.
448	//
449	// Only shape is judged here. The domain rules (non-blank name, positive
450	// version and constraint count, non-negative input counts) keep being
451	// re-checked by validateEnvelope.
452	
453	var persistCircuitFields = []string{
454		"name", "version", "constraints", "public_inputs", "private_inputs",
455		"frozen", "description", "definition",
456	}
457	
458	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
459	// tagged for committed data: every structural failure in a stored circuit
460	// record is data corruption, never a bad request.
461	var storedRecordShape = jsonShape{fail: corruptf}
462	
463	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
464		const what = "stored circuit record"
465		if string(bytes.TrimSpace(raw)) == "null" {
466			return corruptf("%s must be a JSON object, not null", what)
467		}
468		members, err := strictCircuitObject(raw, what)
469		if err != nil {
470			return err
471		}
472	
473		var out persistCircuit
474	
475		requireString := func(key string, dst *string) error {
476			r, err := storedRecordShape.require(members, key, what)
477			if err != nil {
478				return err
479			}
480			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
481			if err != nil {
482				return err
483			}
484			*dst = v
485			return nil
486		}
487		requireInt := func(key string, dst *int) error {
488			r, err := storedRecordShape.require(members, key, what)
489			if err != nil {
490				return err
491			}
492			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
493			if err != nil {
494				return err
495			}
496			*dst = v
497			return nil
498		}
499	
500		if err := requireString("name", &out.Name); err != nil {
501			return err
502		}
503		// The name is the version's identity and must read back as the exact
504		// value that was committed. encoding/json silently rewrites both invalid
505		// UTF-8 bytes and unpaired \uXXXX surrogate escapes to U+FFFD, so the
506		// decoded string alone cannot tell a damaged name apart from one that
507		// legitimately contains "�". Judge the raw JSON token instead.
508		if err := checkStoredStringEncoding(members["name"], what+` field "name"`, "committed name"); err != nil {
509			return err
510		}
511		if err := requireInt("version", &out.Version); err != nil {
512			return err
513		}
514		if err := requireInt("constraints", &out.Constraints); err != nil {
515			return err
516		}
517		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
518			return err
519		}
520		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
521			return err
522		}
523		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
524		if err != nil {
525			return err
526		}
527		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
528		if err != nil {
529			return err
530		}
531		if err := requireString("description", &out.Description); err != nil {
532			return err
533		}
534	
535		// definition is the only optional member: absent or null both mean the
536		// counts-only legacy state.
537		if defRaw, present := members["definition"]; present {
538			if string(bytes.TrimSpace(defRaw)) != "null" {
539				var def persistDefinition
540				if err := json.Unmarshal(defRaw, &def); err != nil {
541					var se StoreError
542					if errors.As(err, &se) {
543						return err // already reported as data corruption
544					}
545					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
546				}
547				out.Definition = &def
548			}
549		}
550	
551		*c = out
552		return nil
553	}
554	
555	// strictCircuitObject decodes one committed circuit record's own member map,
556	// demanding a JSON object with exactly the known top-level fields once.
557	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
558		return strictObjectMembers(raw, what, persistCircuitFields)
559	}
560	
561	// checkStoredStringEncoding enforces an identity field's exact-readback rule
562	// on the raw JSON string token of a committed value (a circuit record's name,
563	// a job record's id). The string has already been decoded by the strict
564	// member read, so the token is known to be one complete, well-formed JSON
565	// string; this walk judges only what that decode silently repairs:
566	//
567	//   - invalid UTF-8 bytes in the literal (unescaped) portions — a lone
568	//     continuation byte, a truncated multi-byte character, an overlong
569	//     form — which encoding/json rewrites to U+FFFD, and
570	//   - \uXXXX escapes forming an unpaired surrogate — a high surrogate not
571	//     immediately followed by its low-surrogate escape, or a low surrogate
572	//     standing alone — which are rewritten to U+FFFD the same way.
573	//
574	// Both would make the record read back under a different value than the bytes
575	// on disk carry, so the record is data corruption rather than a value that
576	// legitimately decodes to a replacement character it never had. noun is the
577	// word naming the value in diagnostics ("committed name" / "committed job
578	// id"); what locates the record and field, e.g.
579	// `stored circuit record field "name"` or `stored job record "j1" field
580	// "id"`. A legal surrogate pair decodes to its astral character, an actually
581	// committed "�" (written directly or as a U+FFFD escape) is an ordinary
582	// value, and the literal six characters "\uD800" — written with an escaped
583	// backslash — carry no escape at all: all three keep their exact value.
584	func checkStoredStringEncoding(raw json.RawMessage, what, noun string) error {
585		token := bytes.TrimSpace(raw)
586		// The token is a complete JSON string (the strict string read above
587		// succeeded), so every escape is well-formed and the walk stays in
588		// bounds; only the replacement-prone content is judged.
589		for i := 1; i < len(token)-1; {
590			c := token[i]
591			if c == '\\' {
592				if token[i+1] != 'u' {
593					i += 2 // a simple escape: \" \\ \/ \b \f \n \r \t
594					continue
595				}
596				code, _ := strconv.ParseUint(string(token[i+2:i+6]), 16, 32)
597				switch {
598				case code >= 0xD800 && code <= 0xDBFF:
599					// A high surrogate is whole only when its low-surrogate
600					// escape follows immediately.
601					if i+12 <= len(token) && token[i+6] == '\\' && token[i+7] == 'u' {
602						lo, _ := strconv.ParseUint(string(token[i+8:i+12]), 16, 32)
603						if lo >= 0xDC00 && lo <= 0xDFFF {
604							i += 12
605							continue
606						}
607					}
608					return corruptf("%s contains an unpaired high surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
609				case code >= 0xDC00 && code <= 0xDFFF:
610					return corruptf("%s contains an unpaired low surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
611				}
612				i += 6
613				continue
614			}
615			if c < utf8.RuneSelf {
616				i++
617				continue
618			}
619			r, size := utf8.DecodeRune(token[i:])
620			if r == utf8.RuneError && size == 1 {
621				return corruptf("%s contains invalid UTF-8 bytes; the %s would not read back unchanged", what, noun)
622			}
623			i += size
624		}
625		return nil
626	}
627	
628	// strictObjectMembers decodes one committed record's own member map,
629	// demanding a JSON object without repeated keys. A non-nil allowed list
630	// restricts which keys may appear; nil allows any key. It scans only the
631	// record's own level: the envelope scanner already attributes a duplicated
632	// top-level key to this record, and nested values such as the constraint
633	// definition own their (more precise) strict decoders. Keys are compared
634	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
635	// still a duplicate, even when both values are identical.
636	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
637		trimmed := bytes.TrimSpace(raw)
638		if len(trimmed) == 0 || trimmed[0] != '{' {
639			return nil, corruptf("%s must be a JSON object", what)
640		}
641		dec := json.NewDecoder(bytes.NewReader(trimmed))
642		dec.UseNumber()
643		open, err := dec.Token()
644		if err != nil || open != json.Delim('{') {
645			return nil, corruptf("%s must be a JSON object", what)
646		}
647		var allowed map[string]bool
648		if allowedFields != nil {
649			allowed = make(map[string]bool, len(allowedFields))
650			for _, f := range allowedFields {
651				allowed[f] = true
652			}
653		}
654		members := make(map[string]json.RawMessage)
655		for dec.More() {
656			keyTok, err := dec.Token()
657			if err != nil {
658				return nil, corruptf("%s is not valid JSON: %v", what, err)
659			}
660			key, ok := keyTok.(string)
661			if !ok {
662				return nil, corruptf("%s is not valid JSON", what)
663			}
664			if allowed != nil && !allowed[key] {
665				return nil, corruptf("%s has unknown field %q", what, key)
666			}
667			if _, repeated := members[key]; repeated {
668				return nil, corruptf("%s contains duplicate field %q", what, key)
669			}
670			var value json.RawMessage
671			if err := dec.Decode(&value); err != nil {
672				return nil, corruptf("%s is not valid JSON: %v", what, err)
673			}
674			members[key] = value
675		}
676		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
677			return nil, corruptf("%s is not valid JSON", what)
678		}
679		if _, err := dec.Token(); err != io.EOF {
680			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
681		}
682		return members, nil
683	}
684	
685	type persistSetup struct {
686		Name    string `json:"name"`
687		Version int    `json:"version"`
688	}
689	
690	// Store is a persistent workbench backed by one local data directory.
691	//
692	// All operations are safe for concurrent use by multiple goroutines and by
693	// several processes pointed at the same directory: an in-process mutex plus a
694	// process-shared flock serialize commits, and every commit is an atomic
695	// temp-file/fsync/rename replacement. Open the directory with Open and call
696	// Close when done.
697	type Store struct {
698		dir  string
699		mu   sync.Mutex
700		lock *os.File
701	
702		data envelope
703	}
704	
705	// Open opens (creating if needed) the workbench data in dir. If the
706	// directory does not exist it is created. Existing committed data is loaded
707	// and fully validated before Open returns; on a corrupt, truncated or
708	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
709	// leaves every file in the directory untouched.
710	//
711	// dir is resolved against the process's current working directory at Open
712	// time and pinned for the store's lifetime: a relative path such as
713	// "bench-data" names one fixed directory from the moment Open succeeds, and
714	// later working-directory changes never redirect the store's reads, writes,
715	// lock or Dir to another location. Paths to constraint definitions and input
716	// files passed to individual operations are not pinned this way — they keep
717	// being resolved against the caller's working directory at call time.
718	func Open(dir string) (*Store, error) {
719		if dir == "" {
720			return nil, invalidf("data directory must not be empty")
721		}
722		// Pin the location now: a relative path would otherwise be re-resolved
723		// against the process working directory on every later file access, so a
724		// chdir after Open could silently move the store onto a different
725		// bench-data. Abs (not EvalSymlinks) so a not-yet-existing directory can
726		// still be created below.
727		absDir, err := filepath.Abs(dir)
728		if err != nil {
729			return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
730		}
731		dir = absDir
732		if err := os.MkdirAll(dir, 0o755); err != nil {
733			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
734		}
735		lockPath := filepath.Join(dir, dirLockFile)
736		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
737		if err != nil {
738			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
739		}
740		// Serialize against other processes while we read / validate.
741		if err := lockExclusive(lock); err != nil {
742			lock.Close()
743			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
744		}
745	
746		s := &Store{dir: dir, lock: lock}
747		if err := s.loadLocked(); err != nil {
748			unlockLock(lock)
749			lock.Close()
750			return nil, err
751		}
752		// The lock is taken again per operation; holding it for the store's
753		// lifetime would forbid two open handles on one directory.
754		if err := unlockLock(lock); err != nil {
755			lock.Close()
756			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
757		}
758		return s, nil
759	}
760	
761	// Close releases the directory lock. It does not discard committed data.
762	func (s *Store) Close() error {
763		s.mu.Lock()
764		defer s.mu.Unlock()
765		if s.lock == nil {
766			return nil
767		}
768		var first error
769		if err := unlockLock(s.lock); err != nil {
770			first = err
771		}
772		if err := s.lock.Close(); err != nil && first == nil {
773			first = err
774		}
775		s.lock = nil
776		return first
777	}
778	
779	// Dir reports the data directory backing the store.
780	func (s *Store) Dir() string { return s.dir }
781	
782	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
783	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
784	
785	// loadLocked reads and validates the committed file. Caller must hold the
786	// exclusive flock; the in-process mutex is taken by the public Open path.
787	func (s *Store) loadLocked() error {
788		raw, err := os.ReadFile(s.dataPath())
789		if errors.Is(err, os.ErrNotExist) {
790			s.data = envelope{Format: FormatVersion}
791			return nil
792		}
793		if err != nil {
794			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
795		}
796		if len(strings.TrimSpace(string(raw))) == 0 {
797			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
798		}
799	
800		var env envelope
801		if err := json.Unmarshal(raw, &env); err != nil {
802			// Shape failures surfaced by the persisted-definition decoders are
803			// integrity failures, not JSON syntax errors; report their detail
804			// instead of the generic "not valid JSON" wording.
805			var se StoreError
806			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
807				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
808			}
809			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
810		}
811		if env.Format == 0 {
812			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
813		}
814		if env.Format != FormatVersion {
815			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
816				s.dataPath(), env.Format, FormatVersion)
817		}
818		if err := validateEnvelope(env); err != nil {
819			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
820		}
821		s.data = env
822		return nil
823	}
824	
825	// commitLocked writes the pending state atomically: temp file → fsync →
826	// rename → fsync directory. Caller must hold both the in-process mutex and
827	// the exclusive flock; all in-memory mutations must already have happened and
828	// been rule-checked, so a failure here occurs before any success is reported.
829	func (s *Store) commitLocked() error {
830		s.data.Format = FormatVersion
831		// Stable output: records are stored sorted so files are deterministic.
832		sortEnvelope(&s.data)
833	
834		payload, err := json.MarshalIndent(&s.data, "", "  ")
835		if err != nil {
836			return fmt.Errorf("cannot encode data: %w", err)
837		}
838		payload = append(payload, '\n')
839	
840		tmp := s.tmpPath()
841		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
842		if err != nil {
843			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
844		}
845		if _, err := f.Write(payload); err != nil {
846			f.Close()
847			os.Remove(tmp)
848			return fmt.Errorf("cannot write staged data: %w", err)
849		}
850		if err := f.Sync(); err != nil {
851			f.Close()
852			os.Remove(tmp)
853			return fmt.Errorf("cannot flush staged data: %w", err)
854		}
855		if err := f.Close(); err != nil {
856			os.Remove(tmp)
857			return fmt.Errorf("cannot finish staged data: %w", err)
858		}
859		if err := os.Rename(tmp, s.dataPath()); err != nil {
860			os.Remove(tmp)
861			return fmt.Errorf("cannot commit data file: %w", err)
862		}
863		if err := syncDir(s.dir); err != nil {
864			// The rename already happened; lack of dir fsync only weakens crash
865			// durability, never correctness of what is visible now.
866			return nil
867		}
868		return nil
869	}
870	
871	// withLock runs fn under the in-process mutex and an exclusive flock, then
872	// atomically commits when fn requests it. The on-disk state is re-read after
873	// acquiring the lock, so concurrent commits from another process or another
874	// handle are always observed. Operations validate before mutating; a rejected
875	// operation (commit=false or an error) writes nothing and leaves committed
876	// state unchanged.
877	func (s *Store) withLock(fn func() (commit bool, err error)) error {
878		s.mu.Lock()
879		defer s.mu.Unlock()
880		if s.lock == nil {
881			return invalidf("store is closed")
882		}
883		if err := lockExclusive(s.lock); err != nil {
884			return fmt.Errorf("cannot lock data directory: %w", err)
885		}
886		defer unlockLock(s.lock)
887	
888		if err := s.loadLocked(); err != nil {
889			return err
890		}
891		commit, err := fn()
892		if err != nil {
893			return err
894		}
895		if !commit {
896			return nil
897		}
898		return s.commitLocked()
899	}
900	
901	// withLockRead runs fn under a shared flock over freshly reloaded state.
902	func (s *Store) withLockRead(fn func() error) error {
903		s.mu.Lock()
904		defer s.mu.Unlock()
905		if s.lock == nil {
906			return invalidf("store is closed")
907		}
908		if err := lockShared(s.lock); err != nil {
909			return fmt.Errorf("cannot lock data directory: %w", err)
910		}
911		defer unlockLock(s.lock)
912		if err := s.loadLocked(); err != nil {
913			return err
914		}
915		return fn()
916	}
917	
918	func sortEnvelope(env *envelope) {
919		sort.Slice(env.Circuits, func(i, j int) bool {
920			if env.Circuits[i].Name != env.Circuits[j].Name {
921				return env.Circuits[i].Name < env.Circuits[j].Name
922			}
923			return env.Circuits[i].Version < env.Circuits[j].Version
924		})
925		sort.Slice(env.Setups, func(i, j int) bool {
926			if env.Setups[i].Name != env.Setups[j].Name {
927				return env.Setups[i].Name < env.Setups[j].Name
928			}
929			return env.Setups[i].Version < env.Setups[j].Version
930		})
931		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
932		sort.Slice(env.Artifacts, func(i, j int) bool {
933			if env.Artifacts[i].Name != env.Artifacts[j].Name {
934				return env.Artifacts[i].Name < env.Artifacts[j].Name
935			}
936			return env.Artifacts[i].Version < env.Artifacts[j].Version
937		})
938	}
939	
940	// validateEnvelope re-checks every invariant on load so a tampered or
941	// hand-edited file cannot bypass the domain rules.
942	func validateEnvelope(env envelope) error {
943		seenCircuit := make(map[[2]string]bool)
944		circuitOK := make(map[[2]string]bool)
945		for i, c := range env.Circuits {
946			key := [2]string{c.Name, itoa(c.Version)}
947			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
948				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
949			}
950			if c.Version <= 0 {
951				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
952			}
953			if seenCircuit[key] {
954				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
955			}
956			seenCircuit[key] = true
957			if c.Constraints <= 0 {
958				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
959			}
960			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
961				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
962			}
963			// The same representability rule the write path enforces: wire 0 plus
964			// every declared input must fit inside the platform's int. A record
965			// beyond that bound can never have been written by this build and
966			// cannot be checked safely, so the directory is corrupt rather than
967			// silently narrowed or read with a wrapped-around layout.
968			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
969				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
970					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
971			}
972			if c.Definition != nil {
973				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
974					return err
975				}
976			}
977			circuitOK[key] = true
978		}
979		seenSetup := make(map[[2]string]bool)
980		for i, p := range env.Setups {
981			key := [2]string{p.Name, itoa(p.Version)}
982			if !circuitOK[key] {
983				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
984			}
985			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
986			if c == nil || !c.Frozen {
987				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
988			}
989			if seenSetup[key] {
990				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
991			}
992			seenSetup[key] = true
993		}
994		seenJob := make(map[string]bool)
995		for i, j := range env.Jobs {
996			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
997				return fmt.Errorf("job #%d has an empty or blank id", i+1)
998			}
999			if seenJob[j.ID] {
1000				return fmt.Errorf("job %q appears more than once", j.ID)
1001			}
1002			seenJob[j.ID] = true
1003			if j.Kind != "prove" {
1004				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1005			}
1006			if j.Attempt <= 0 {
1007				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1008			}
1009			key := [2]string{j.Circuit, itoa(j.Version)}
1010			if !circuitOK[key] {
1011				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1012			}
1013			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1014			if c == nil || !c.Frozen {
1015				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1016			}
1017			if !seenSetup[key] {
1018				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1019			}
1020			// A recorded compiled-artifact binding must still resolve against the
1021			// pinned version's artifact; a dangling or mismatched binding makes
1022			// the file unreadable rather than silently dropping the binding.
1023			if j.CompiledHash != "" {
1024				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1025				if artifact == nil {
1026					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1027				}
1028				if artifact.Hash != j.CompiledHash {
1029					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1030						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1031				}
1032			}
1033		}
1034		seenArtifact := make(map[[2]string]bool)
1035		for i, a := range env.Artifacts {
1036			key := [2]string{a.Name, itoa(a.Version)}
1037			if !circuitOK[key] {
1038				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1039			}
1040			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1041			if c == nil || !c.Frozen {
1042				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1043			}
1044			if seenArtifact[key] {
1045				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1046			}
1047			seenArtifact[key] = true
1048			if c.Definition == nil {
1049				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1050			}
1051			if a.Constraints != c.Constraints {
1052				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1053					a.Name, a.Version, a.Constraints, c.Constraints)
1054			}
1055			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1056			if err != nil {
1057				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1058			}
1059			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1060				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1061			}
1062			wantHash := artifactHash(a.Name, a.Version, def)
1063			if a.Hash != wantHash {
1064				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1065					a.Name, a.Version, a.Hash, wantHash)
1066			}
1067		}
1068		return nil
1069	}
1070	
1071	// validatePersistDefinition re-validates a stored definition against its
1072	// version's declared counts: prime modulus, in-range wires and an exact
1073	// constraint count match.
1074	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1075		parsed, err := definitionFromPersist(*def, public, private)
1076		if err != nil {
1077			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1078		}
1079		if !parsed.compatibleWith(constraints, public, private) {
1080			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1081		}
1082		return nil
1083	}
1084	
1085	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1086		for i := range cs {
1087			if cs[i].Name == name && cs[i].Version == version {
1088				return &cs[i]
1089			}
1090		}
1091		return nil
1092	}
1093	
1094	func itoa(v int) string { return fmt.Sprintf("%d", v) }
1095

